// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt. Scoped CSS is precompiled.
"use client";
import * as React from "react";
import { cn } from "./utils";
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from "embla-carousel-react";
import { ArrowLeft, ArrowRight } from "lucide-react";
import { Button } from "./button";
type CarouselApi = UseEmblaCarouselType[1];
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>;
type CarouselOptions = UseCarouselParameters[0];
type CarouselPlugin = UseCarouselParameters[1];
type CarouselProps = {
  opts?: CarouselOptions;
  plugins?: CarouselPlugin;
  orientation?: "horizontal" | "vertical";
  setApi?: (api: CarouselApi) => void;
};
type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0];
  api: ReturnType<typeof useEmblaCarousel>[1];
  scrollPrev: () => void;
  scrollNext: () => void;
  canScrollPrev: boolean;
  canScrollNext: boolean;
} & CarouselProps;
const CarouselContext = React.createContext<CarouselContextProps | null>(null);
function useCarousel() {
  const context = React.useContext(CarouselContext);
  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />");
  }
  return context;
}
function Carousel({
  orientation = "horizontal",
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === "horizontal" ? "x" : "y",
    },
    plugins,
  );
  const [canScrollPrev, setCanScrollPrev] = React.useState(false);
  const [canScrollNext, setCanScrollNext] = React.useState(false);
  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return;
    setCanScrollPrev(api.canScrollPrev());
    setCanScrollNext(api.canScrollNext());
  }, []);
  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev();
  }, [api]);
  const scrollNext = React.useCallback(() => {
    api?.scrollNext();
  }, [api]);
  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault();
        scrollPrev();
      } else if (event.key === "ArrowRight") {
        event.preventDefault();
        scrollNext();
      }
    },
    [scrollPrev, scrollNext],
  );
  React.useEffect(() => {
    if (!api || !setApi) return;
    setApi(api);
  }, [api, setApi]);
  React.useEffect(() => {
    if (!api) return;
    onSelect(api);
    api.on("reInit", onSelect);
    api.on("select", onSelect);
    return () => {
      api?.off("select", onSelect);
      api?.off("reInit", onSelect);
    };
  }, [api, onSelect]);
  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === "y" ? "vertical" : "horizontal"),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn("roc-shadcn", cn("roc-u-relative", className))}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  );
}
function CarouselContent({ className, ...props }: React.ComponentProps<"div">) {
  const { carouselRef, orientation } = useCarousel();
  return (
    <div
      ref={carouselRef}
      className={cn("roc-shadcn", "roc-u-overflow-hidden")}
      data-slot="carousel-content"
    >
      <div
        className={cn(
          "roc-shadcn",
          cn(
            "roc-u-flex",
            orientation === "horizontal"
              ? "roc-u--ml-4"
              : "roc-u--mt-4 roc-u-flex-col",
            className,
          ),
        )}
        {...props}
      />
    </div>
  );
}
function CarouselItem({ className, ...props }: React.ComponentProps<"div">) {
  const { orientation } = useCarousel();
  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-min-w-0 roc-u-shrink-0 roc-u-grow-0 roc-u-basis-full",
          orientation === "horizontal"
            ? "roc-u-pl-4"
            : "roc-u-pt-4",
          className,
        ),
      )}
      {...props}
    />
  );
}
function CarouselPrevious({
  className,
  variant = "outline",
  size = "icon",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel();
  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-absolute roc-u-size-8 roc-u-rounded-full",
          orientation === "horizontal"
            ? "roc-u-top-1/2 roc-u--left-12 roc-u--translate-y-1/2"
            : "roc-u--top-12 roc-u-left-1/2 roc-u--translate-x-1/2 roc-u-rotate-90",
          className,
        ),
      )}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <ArrowLeft />
      <span className={cn("roc-shadcn", "roc-u-sr-only")}>
        Previous slide
      </span>
    </Button>
  );
}
function CarouselNext({
  className,
  variant = "outline",
  size = "icon",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollNext, canScrollNext } = useCarousel();
  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn(
        "roc-shadcn",
        cn(
          "roc-u-absolute roc-u-size-8 roc-u-rounded-full",
          orientation === "horizontal"
            ? "roc-u-top-1/2 roc-u--right-12 roc-u--translate-y-1/2"
            : "roc-u--bottom-12 roc-u-left-1/2 roc-u--translate-x-1/2 roc-u-rotate-90",
          className,
        ),
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ArrowRight />
      <span className={cn("roc-shadcn", "roc-u-sr-only")}>Next slide</span>
    </Button>
  );
}
export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
};

import "./carousel.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

