/*! tailwindcss v4.3.3 | MIT License | https://tailwindcss.com */
@layer properties;
.roc-shadcn {
  --roc-sh-spacing: 0.25rem;
}
.roc-u-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border-width: 0;
}
.roc-u-absolute {
  position: absolute;
}
.roc-u-relative {
  position: relative;
}
.roc-u--top-12 {
